<script setup lang="ts">
const context=useDoctorNativeContext(),route=useRoute(),shell=useDoctorMobile(),{t}=useI18n(),{auth,readiness}=useDoctorNativeAuth()
watch(()=>route.path,path=>{void shell.navigate(path)},{immediate:true})
const copy=computed(()=>({title:t('product.name'),description:t(`destination.${shell.state.route.slice(1)}`),notice:t('notice'),retry:t('retry')}))
const view=computed(()=>{if(auth.identity()&&['choosing','loading','switching','error'].includes(context.state.phase))return{state:context.state.phase==='choosing'?'info' as const:context.state.phase==='error'?'error' as const:'loading' as const,title:t('context.choose'),description:context.state.phase==='choosing'?t(context.state.options.length?'context.chooseHelp':'context.noScopes'):t('phase.'+(context.state.phase==='error'?'error':'loading')+'.body'),retry:context.state.phase==='error'||context.state.phase==='choosing',context:null};return{state:({loading:'loading','signed-out':'empty',denied:'denied',offline:'info',error:'error',ready:'success'} as const)[shell.state.phase],title:t(`phase.${shell.state.phase}.title`),description:t(`phase.${shell.state.phase}.body`),retry:!['loading','signed-out'].includes(shell.state.phase),context:shell.state.phase==='ready'&&context.state.current?`${context.state.current.practiceName} · ${context.state.current.locationName}`:null,action:shell.state.phase==='signed-out'&&readiness.value==='enabled'?t('auth.signIn'):undefined}})
</script>
<template><BsMobileAccessPage :copy="copy" :view="view" @retry="context.refresh().then(()=>shell.retry())" @action="navigateTo('/sign-in')"/></template>
